<?php require '../includes/functions.php';$u=require_role('super_admin');$pdo=db();$s=$pdo->query("SELECT (SELECT COUNT(*) FROM users WHERE role_id=(SELECT id FROM roles WHERE name='citizen') AND is_active=1) citizens,(SELECT COUNT(*) FROM departments WHERE is_active=1) departments,(SELECT COUNT(*) FROM grievances) total,(SELECT COUNT(*) FROM grievances WHERE status IN ('Submitted','Under Review','Assigned','Reopened')) pending,(SELECT COUNT(*) FROM grievances WHERE status IN ('Resolved','Closed')) resolved,(SELECT COUNT(*) FROM grievances WHERE status='Rejected') rejected,(SELECT COUNT(*) FROM grievances WHERE expected_resolution_date<CURDATE() AND status NOT IN ('Resolved','Closed','Rejected')) overdue")->fetch();$pageTitle='System dashboard';require '../includes/header.php';?><h1>System dashboard</h1><div class="grid"><?php foreach(['Citizens'=>'citizens','Departments'=>'departments','Grievances'=>'total','Pending'=>'pending','Resolved'=>'resolved','Rejected'=>'rejected','Overdue'=>'overdue'] as $l=>$k):?><div class="card"><span><?=e($l)?></span><strong><?= (int)$s[$k]?></strong></div><?php endforeach?></div><div class="actions"><a class="button" href="<?=e(url('admin/manage.php'))?>">Manage system</a><a class="button" href="<?=e(url('admin/reports.php'))?>">Reports / CSV export</a><a class="button" href="<?=e(url('admin/audit.php'))?>">Audit log</a></div><?php require '../includes/footer.php';?>
